BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout = '8s';
WITH wanted(schema_name,function_name) AS (VALUES ('public','claim_starter_board_jobs'),('public','finish_starter_board_job'),('fhfh_internal','enqueue_starter_board_game'),('fhfh_internal','enqueue_starter_board_observation'),('fhfh_internal','enqueue_starter_board_resolution'),('public','enqueue_forge_cadence_slot'),('fhfh_internal','advance_forge_cadence_slots'))
SELECT w.schema_name,w.function_name,p.oid IS NOT NULL AS exists,
 CASE WHEN p.oid IS NOT NULL THEN pg_catalog.pg_get_function_identity_arguments(p.oid) END AS identity_arguments,
 CASE WHEN p.oid IS NOT NULL THEN pg_catalog.pg_get_function_result(p.oid) END AS result_type,
 pg_catalog.pg_get_userbyid(p.proowner) AS owner,p.prosecdef AS security_definer,p.provolatile AS volatility,p.proconfig AS settings,p.proacl::text AS acl,
 CASE WHEN p.oid IS NOT NULL THEN octet_length(pg_catalog.pg_get_functiondef(p.oid))>65536 ELSE false END AS over_definition_byte_limit,
 CASE WHEN p.oid IS NOT NULL AND octet_length(pg_catalog.pg_get_functiondef(p.oid))<=65536 THEN pg_catalog.pg_get_functiondef(p.oid) END AS definition
FROM wanted w LEFT JOIN pg_catalog.pg_namespace n ON n.nspname=w.schema_name
LEFT JOIN pg_catalog.pg_proc p ON p.pronamespace=n.oid AND p.proname=w.function_name AND p.prokind IN ('f','p')
ORDER BY w.schema_name,w.function_name,identity_arguments LIMIT 17;
COMMIT;
